repo_files.token_bucket.py:
"""Atomic token bucket implementation."""

import time
from dataclasses import dataclass


@dataclass
class TokenBucket:
    capacity: float
    refill_rate_per_sec: float
    tokens: float
    last_refill_ts: float

    @classmethod
    def create(cls, capacity: float, refill_rate_per_sec: float) -> "TokenBucket":
        return cls(capacity, refill_rate_per_sec, capacity, 0.0)

    def refill(self, now: float) -> None:
        if self.last_refill_ts == 0.0:
            self.last_refill_ts = now
            return
        delta = max(0.0, now - self.last_refill_ts)
        self.tokens = min(self.capacity, self.tokens + delta * self.refill_rate_per_sec)
        self.last_refill_ts = now

    def try_consume(self, amount: float, now: float) -> bool:
        self.refill(now)
        if self.tokens >= amount:
            self.tokens -= amount
            return True
        return False

repo_files.hierarchy.py:
"""Tiered hierarchy nodes for rate limiting."""

from typing import Dict, Optional
from token_bucket import TokenBucket


class HierarchyNode:
    def __init__(self, name: str, bucket: TokenBucket, parent: Optional["HierarchyNode"] = None):
        self.name = name
        self.bucket = bucket
        self.parent = parent
        self.children: Dict[str, "HierarchyNode"] = {}

    def add_child(self, child: "HierarchyNode") -> None:
        self.children[child.name] = child
        child.parent = self

repo_files.limiter.py:
"""Hierarchical multi-tier rate limiter."""

from typing import List, Optional
from hierarchy import HierarchyNode
from token_bucket import TokenBucket


class HierarchicalRateLimiter:
    def __init__(self, root: HierarchyNode):
        self.root = root

    def _get_path_to_node(self, node: HierarchyNode) -> List[HierarchyNode]:
        path = []
        curr: Optional[HierarchyNode] = node
        while curr:
            path.append(curr)
            curr = curr.parent
        return list(reversed(path))

    def allow_request(self, target_node: HierarchyNode, amount: float, now: float) -> bool:
        path = self._get_path_to_node(target_node)
        # BUG: Checks each bucket independently without 2-phase reserve or rollback
        # If root fails after child consumed, child tokens are lost!
        # AND child consumes without guaranteeing all ancestors can satisfy amount.
        for n in path:
            n.bucket.refill(now)
            if n.bucket.tokens < amount:
                return False
        # Consume from child only instead of all tiers up the hierarchy!
        target_node.bucket.tokens -= amount
        return True

